  gap: var(--space-lg);
}
.menu-links a {
  color: var(--color-primary);
  font-size: var(--font-size-lg);
  font-family: var(--font-family-accent);
  text-decoration: none;
  padding: var(--space-xs) var(--space-md);
  border-radius: var(--radius-md);
  transition: var(--transition-fast);
  display: inline-flex;
  align-items: center;
}
.menu-links a .icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-right: 8px;
  /* inherit the link color so icons follow hover/active text color */
  color: inherit;
}
.menu-links a .label { display: inline-block; }
.menu-links a.active,
.menu-links a:hover {
  background: var(--color-accent);
  color: #fff;
}

/* Logout button: visually consistent with links but distinct color and aligned to the right */
.menu-links .nav-logout {
  margin-left: auto;
  background: transparent;
  color: var(--color-error);
  font-size: var(--font-size-lg);
  font-family: var(--font-family-accent);
  padding: var(--space-xs) var(--space-md);
  border-radius: var(--radius-md);
  border: none;
  cursor: pointer;
  transition: var(--transition-fast);
  display: inline-flex;
  align-items: center;
}
.menu-links .nav-logout:hover {
  background: var(--color-error);
  color: #fff;
}

@media (max-width: 700px) {
  .main-navbar {
    padding: var(--space-md);
    border-radius: 0 0 var(--radius-lg) var(--radius-lg);
    width: auto;
    left: 0;
    transform: none;
  }
  .menu-icon {
    display: flex;
  }
  .menu-links {
    display: none;
    flex-direction: column;
    position: absolute;
    top: 100%;
    left: 0;
    width: 100%;
    background: var(--color-surface);
    box-shadow: var(--shadow-md);
    border-radius: 0 0 var(--radius-lg) var(--radius-lg);
    padding: var(--space-md);
    z-index: 10;
  }
  .menu-toggle:checked ~ .menu-links {
    display: flex;
  }
}

