import { Injectable, signal, computed, WritableSignal, Signal } from '@angular/core';
import {
  onAuthStateChanged,
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword,
  signOut,
  deleteUser,
  User as FirebaseAuthUser,
} from 'firebase/auth';
import { doc, getDoc, setDoc, deleteDoc, serverTimestamp } from 'firebase/firestore';
import { auth, db } from '../firebase.config';
import { ToastService } from './toast.service';
import type { User as AppUser } from '../models/user';

@Injectable({ providedIn: 'root' })
export class AuthService {
  private _firebaseUser: WritableSignal<FirebaseAuthUser | null> = signal<FirebaseAuthUser | null>(null);
  private _appUser: WritableSignal<AppUser | null> = signal<AppUser | null>(null);
  private _loading: WritableSignal<boolean> = signal<boolean>(true);
  private _error: WritableSignal<string | null> = signal<string | null>(null);

  public currentUser: Signal<AppUser | null> = computed(() => this._appUser());
  public isLoggedIn: Signal<boolean> = computed(() => !!this._appUser());
  public loading: Signal<boolean> = computed(() => this._loading());
  public uid: Signal<string | null> = computed(() => (this._firebaseUser() ? this._firebaseUser()!.uid : null));
  public error: Signal<string | null> = computed(() => this._error());

  constructor(private toast: ToastService) {
    this._loading.set(true);

    onAuthStateChanged(auth, async (firebaseUser) => {
      this._firebaseUser.set(firebaseUser ?? null);

      if (firebaseUser) {
        try {
          const uid = firebaseUser.uid;
          const ref = doc(db, 'users', uid);
          const snap = await getDoc(ref);

          if (snap.exists()) {
            const data = snap.data() as AppUser;
            this._appUser.set(data);
          } else {
            const defaultUser: AppUser = {
              uid,
              name: firebaseUser.displayName || uid,
              email: firebaseUser.email || '',
              avatarUrl: (firebaseUser.photoURL as string) || null,
              preferences: {
                diet: [],
                dailyCalorieGoal: 2000,
                householdSize: 1,
                measurementSystem: 'metric',
                theme: 'light',
              },
              createdAt: new Date().toISOString(),
              updatedAt: new Date().toISOString(),
            };

            await setDoc(ref, { ...defaultUser, createdAt: serverTimestamp() });
            this._appUser.set(defaultUser);
          }
        } catch (err) {
          const msg = (err as Error).message || 'Ismeretlen hiba az auth betöltésekor';
          this._error.set(msg);
          this.toast.error(msg);
        }
      } else {
        this._appUser.set(null);
      }

      this._loading.set(false);
    });
  }

  public async register(name: string, email: string, password: string): Promise<void> {
    try {
      const cred = await createUserWithEmailAndPassword(auth, email, password);
      const firebaseUser = cred.user;
      const uid = firebaseUser.uid;

      const appUser: AppUser = {
        uid,
        name,
        email,
        avatarUrl: (firebaseUser.photoURL as string) || null,
        preferences: {
          diet: [],
          dailyCalorieGoal: 2000,
          householdSize: 1,
          measurementSystem: 'metric',
          theme: 'light',
        },
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };

      await setDoc(doc(db, 'users', uid), { ...appUser, createdAt: serverTimestamp() });
      this.toast.success('Regisztráció sikeres.');
    } catch (err) {
      const msg = (err as Error).message || 'Hiba történt regisztráció közben.';
      this._error.set(msg);
      this.toast.error(msg);
      throw err;
    }
  }

  public async login(email: string, password: string): Promise<void> {
    try {
      await signInWithEmailAndPassword(auth, email, password);
      this.toast.success('Bejelentkezés sikeres.');
    } catch (_err) {
      const msg = 'Hibás email vagy jelszó';
      this._error.set(msg);
      this.toast.error(msg);
      throw new Error(msg);
    }
  }

  public async logout(): Promise<void> {
    try {
      await signOut(auth);
      this.toast.success('Kijelentkezés sikeres.');
    } catch (err) {
      const msg = (err as Error).message || 'Hiba a kijelentkezéskor.';
      this._error.set(msg);
      this.toast.error(msg);
      throw err;
    }
  }

  public async deleteAccount(): Promise<void> {
    const firebaseUser = this._firebaseUser();
    if (!firebaseUser) {
      const msg = 'Nincs bejelentkezett felhasználó.';
      this._error.set(msg);
      this.toast.error(msg);
      throw new Error(msg);
    }

    try {
      // Delete from Firebase Auth
      await deleteUser(firebaseUser);

      // Delete Firestore profile
      await deleteDoc(doc(db, 'users', firebaseUser.uid));

      this.toast.success('Fiók törölve.');
    } catch (err) {
      const msg = (err as Error).message || 'Hiba a fiók törlése közben.';
      this._error.set(msg);
      this.toast.error(msg);
      throw err;
    }
  }

  // Update the stored app user with a partial patch
  public updateAppUser(patch: Partial<AppUser>) {
    this._appUser.update((u) => {
      if (!u) return u;
      const next: AppUser = { ...u } as AppUser;
      if (patch.name !== undefined) next.name = patch.name;
      if (patch.email !== undefined) next.email = patch.email;
      if (patch.avatarUrl !== undefined) next.avatarUrl = patch.avatarUrl;
      if (patch.preferences) {
        next.preferences = { ...next.preferences, ...patch.preferences } as AppUser['preferences'];
      }
      next.updatedAt = new Date().toISOString();
      return next;
    });
  }
}

import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, Validators, FormGroup } from '@angular/forms';
import { ProfileService } from '../services/profile.service';
import { AuthService } from '../services/auth.service';
import { Router } from '@angular/router';
import { ToastService } from '../services/toast.service';
import { doc, setDoc, serverTimestamp } from 'firebase/firestore';
import { db } from '../firebase.config';

@Component({
  selector: 'app-profile',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './profile.html',
  styleUrl: './profile.scss',
})
export class Profile implements OnInit {
  form!: FormGroup;

  constructor(
    private fb: FormBuilder,
    private profileService: ProfileService,
    private authService: AuthService,
    private router: Router,
    private toast: ToastService
  ) {}

  ngOnInit() {
    // initialize form from AuthService current user
    const u = this.authService.currentUser();
    if (!u) {
      // guard should prevent this, but redirect as a safeguard
      this.router.navigate(['/login']);
      return;
    }

    const d = Array.isArray(u.preferences?.diet) ? u.preferences.diet : [];
    this.form = this.fb.group({
      name: [u.name, Validators.required],
      email: [u.email, [Validators.required, Validators.email]],
      password: [''],
      vegetarian: [d.includes('vegetarian')],
      vegan: [d.includes('vegan')],
      glutenFree: [d.includes('glutenFree')],
      lactoseFree: [d.includes('lactoseFree')],
      calorie: [u.preferences?.dailyCalorieGoal ?? 2000, [Validators.required, Validators.min(1200), Validators.max(3500)]],
      household: [u.preferences?.householdSize ?? 1, [Validators.required, Validators.min(1), Validators.max(8)]],
      theme: [u.preferences?.theme ?? 'light'],
      units: [u.preferences?.measurementSystem ?? 'metric'],
    });
  }

  async saveProfile(): Promise<void> {
    const v = this.form.value;
    const user = this.authService.currentUser();
    if (!user) {
      this.toast.error('Nincs bejelentkezett felhasználó.');
      await this.router.navigate(['/login']);
      return;
    }

    const uid = user.uid;

    const updated = {
      name: v.name ?? user.name,
      email: v.email ?? user.email,
      preferences: {
        diet: [ ...(v.vegetarian ? ['vegetarian'] : []), ...(v.vegan ? ['vegan'] : []), ...(v.glutenFree ? ['glutenFree'] : []), ...(v.lactoseFree ? ['lactoseFree'] : []) ],
        dailyCalorieGoal: Number(v.calorie),
        householdSize: Number(v.household),
        measurementSystem: (v.units ?? user.preferences.measurementSystem),
        theme: (v.theme ?? user.preferences.theme),
      },
      updatedAt: new Date().toISOString(),
    } as any;

    try {
      await setDoc(doc(db, 'users', uid), { ...user, ...updated, updatedAt: serverTimestamp() }, { merge: true });
      // Update local profile service so UI and theme reflect changes
      this.profileService.replaceProfile({ user: { name: updated.name, email: updated.email }, diets: updated.preferences.diet, calorie: updated.preferences.dailyCalorieGoal, household: updated.preferences.householdSize, theme: updated.preferences.theme, units: updated.preferences.measurementSystem });
      // keep AuthService in sync so other parts of app reflect changes immediately
      this.authService.updateAppUser({ name: updated.name, email: updated.email, preferences: updated.preferences as any });
      this.toast.success('Profil mentve');
    } catch (err) {
      const msg = (err as Error).message || 'Hiba a profil mentésekor';
      this.toast.error(msg);
    }
  }

  toggleTheme() {
    const current = this.profileService.theme();
    const next = current === 'dark' ? 'light' : 'dark';
    this.profileService.setTheme(next);
    // keep form in sync
    this.form.patchValue({ theme: next });
  }

  logout() {
    this.authService.logout().then(() => this.router.navigate(['/login'])).catch(() => {});
  }

  deleteAccount() {
    if (confirm('Biztosan törlöd a fiókodat? Ez visszafordíthatatlan.')) {
      this.authService.deleteAccount().then(() => this.router.navigate(['/login'])).catch(() => {});
    }
  }

  // helper for template to read toast signal
  get toastVisible() {
    return this.profileService.toastVisible();
  }
}

