      list = list.filter(r => r.difficulty === difficulty);
    }

    if (typeof maxPrep === 'number') {
      list = list.filter(r => typeof r.prepTime === 'number' && r.prepTime <= maxPrep);
    }

    // sorting
    if (sort === 'titleAsc') {
      list = [...list].sort((a, b) => a.title.localeCompare(b.title));
    } else if (sort === 'titleDesc') {
      list = [...list].sort((a, b) => b.title.localeCompare(a.title));
    } else if (sort === 'prepTimeAsc') {
      list = [...list].sort((a, b) => (a.prepTime || 0) - (b.prepTime || 0));
    } else if (sort === 'caloriesAsc') {
      list = [...list].sort((a, b) => (a.calories || 0) - (b.calories || 0));
    } else if (sort === 'newest') {
      list = [...list].sort((a, b) => (new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()));
    }

    return list;
  });

  readonly resultCount = computed(() => this.filteredRecipes().length);
  async loadRecipes(): Promise<void> {
    if (this._loading()) return;
    this._loading.set(true);
    this._error.set(null);
    try {
      const q = query(collection(db, 'recipes'), orderBy('createdAt', 'desc'));
      const snapshot = await getDocs(q);
      const recipes = snapshot.docs.map((doc: QueryDocumentSnapshot<DocumentData>) => ({
        ...doc.data(),
        id: doc.id
      }) as Recipe);
      this._recipes.set(recipes);
    } catch (err) {
      console.error('Firestore hiba:', err);
      // If permissions prevent a full collection read, try to at least load public recipes
      // (rules allow read if `isPublic == true`). This provides a degraded-but-usable UX.
      try {
        const publicQuery = query(collection(db, 'recipes'), where('isPublic', '==', true), orderBy('createdAt', 'desc'));
        const snap = await getDocs(publicQuery);
        const publicRecipes = snap.docs.map((d: QueryDocumentSnapshot<DocumentData>) => ({ ...d.data(), id: d.id }) as Recipe);

        // Also try to load recipes owned by the current user and merge results
        const uid = this.auth?.uid?.() ?? null;
        let ownerRecipes: Recipe[] = [];
        if (uid) {
          try {
            const ownerQuery = query(collection(db, 'recipes'), where('ownerId', '==', uid), orderBy('createdAt', 'desc'));
            const ownerSnap = await getDocs(ownerQuery);
            ownerRecipes = ownerSnap.docs.map((d: QueryDocumentSnapshot<DocumentData>) => ({ ...d.data(), id: d.id }) as Recipe);
          } catch (ownerErr) {
            console.warn('Owner-only query failed:', ownerErr);
          }
        }

        // Merge unique recipes by id (owner ones may overlap with public ones)
        const mergedMap = new Map<string, Recipe>();
        publicRecipes.concat(ownerRecipes).forEach(r => mergedMap.set(r.id, r));
        const merged = Array.from(mergedMap.values()).sort((a, b) => (new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()));
        this._recipes.set(merged);

        // If we found any, clear the error; otherwise show a helpful message
        if (merged.length > 0) {
          this._error.set(null);
        } else {
          this._error.set('Nincsenek elérhető receptek — vagy jogosultság hiányzik.');
        }
      } catch (err2) {
        this._error.set('Nem sikerült betölteni a recepteket. Ellenőrizd az internetkapcsolatot vagy jogosultságaidat.');
        console.error('Fallback public query hiba:', err2);
      }
    } finally {
      this._loading.set(false);
    }
  }

  /*
  // Real-time listener reference (példa / kikommentezve)
  private unsubscribe?: Unsubscribe;

  loadRecipesRealtime(): void {
    this._loading.set(true);
    const q = query(collection(db, 'recipes'), orderBy('createdAt', 'desc'));
    this.unsubscribe = onSnapshot(q,
      (snapshot) => {
        const recipes = snapshot.docs.map(doc => ({
          ...doc.data(), id: doc.id
        }) as Recipe);
        this._recipes.set(recipes);
        this._loading.set(false);
      },
      (error) => {
        this._error.set('Valós idejű kapcsolat megszakadt.');
        this._loading.set(false);
      }
    );
  }

  // Komponens elhagyásakor hívandó:
  stopRealtimeListener(): void {
    this.unsubscribe?.();
  }
  */

  async addRecipe(recipe: Recipe): Promise<Recipe | null> {
    try {
      // Prepare payload without id — Firestore will generate it
      const { id, createdAt, updatedAt, ...payload } = recipe as any;
      const dataToSave = {
        ...payload,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp()
      };

      const docRef = await addDoc(collection(db, 'recipes'), dataToSave);

      // Use the generated id for local state. Use a local timestamp approximation for immediate UI.
      const now = new Date().toISOString();
      const localRecipe: Recipe = {
        ...(payload as Recipe),
        id: docRef.id,
        createdAt: now,
        updatedAt: now,
      } as Recipe;

      // pessimistic update: only update local state after successful Firestore write
      this._recipes.update(list => [...list, localRecipe]);

      // notify success
      this.toast?.success?.('Recept sikeresen mentve!');

      return localRecipe;
    } catch (err) {
      console.error('Firestore addDoc error:', err);
      this.toast?.error?.('Nem sikerült menteni a receptet.');
      return null;
    }
  }

  private cleanObject(obj: any): any {
    if (obj == null || typeof obj !== 'object') return obj;
    if (Array.isArray(obj)) return obj;
    const out: any = {};
    Object.entries(obj).forEach(([k, v]) => {
      if (v === undefined) return;
      if (v && typeof v === 'object' && !Array.isArray(v)) {
        const cleaned = this.cleanObject(v);
        if (cleaned !== undefined && (typeof cleaned !== 'object' || Object.keys(cleaned).length > 0)) {
          out[k] = cleaned;
        }
      } else {
        out[k] = v;
      }
    });
    return out;
  }

  async updateRecipe(id: string, changes: Partial<Recipe>): Promise<Recipe | null> {
    try {
      // Do not allow overriding id or createdAt
      const { id: _i, createdAt: _ca, ...rest } = changes as any;
      const cleaned = this.cleanObject(rest) || {};

      // Ensure updatedAt is set server-side
      const payload: any = { ...cleaned, updatedAt: serverTimestamp() };

      const ref = doc(db, 'recipes', id);
      await updateDoc(ref, payload);

      // Update local state (pessimistic): only after successful Firestore update
      const now = new Date().toISOString();
      const list = this._recipes();
      const idx = list.findIndex(r => r.id === id);
      if (idx >= 0) {
        const existing = list[idx];
        const merged: Recipe = {
          ...existing,
          ...cleaned,
          updatedAt: now,
        } as Recipe;
        const newList = [...list];
        newList[idx] = merged;
        this._recipes.set(newList);
        this.toast.success('Recept sikeresen frissítve!');
        return merged;
      } else {
        // If not in local cache, fetch from Firestore and add
        const fresh = await this.getRecipeByIdFromFirestore(id);
        if (fresh) {
          this._recipes.update(l => [...l, fresh as Recipe]);
          this.toast.success('Recept sikeresen frissítve!');
          return fresh as Recipe;
        }
        this.toast.error('A recept nem található frissítés után.');
        return null;
      }
    } catch (err) {
      console.error('Firestore updateDoc error:', err);
      this.toast.error('Nem sikerült frissíteni a receptet.');
      return null;
    }
  }

  async getRecipeByIdFromFirestore(id: string): Promise<Recipe | null> {
    try {
      const ref = doc(db, 'recipes', id);
      const snap = await getDoc(ref);
      if (!snap.exists()) return null;
      return { ...(snap.data() as any), id: snap.id } as Recipe;
    } catch (err) {
      console.error('getDoc error:', err);
      return null;
    }
  }

  async checkRecipeUsage(recipeId: string): Promise<string[]> {
    try {
      const snapshot = await getDocs(collection(db, 'weeklyMenus'));
      const weeks: string[] = [];
      snapshot.docs.forEach(d => {
        const data = d.data() as any;
        const slots = data.slots;
        if (Array.isArray(slots) && slots.some((s: any) => s && s.recipeId === recipeId)) {
          if (data.weekStart) weeks.push(data.weekStart);
          else weeks.push(d.id);
        }
      });
      return weeks;
    } catch (err) {
      console.error('checkRecipeUsage error:', err);
      return [];
    }
  }

  async deleteRecipe(id: string): Promise<boolean> {
    try {
      const ref = doc(db, 'recipes', id);
      await deleteDoc(ref);

      // remove from local cache
      this._recipes.update(list => list.filter(r => r.id !== id));

      this.toast.success('Recept sikeresen törölve!');
      return true;
    } catch (err) {
      console.error('Firestore deleteDoc error:', err);
      this.toast.error('Nem sikerült törölni a receptet.');
      return false;
    }
  }

  getRecipeById(id: string): Recipe | undefined {
    return this._recipes().find(r => r.id === id);
  }

  // filter / sort setters
  setSearchTerm(term: string) {
    this._searchTerm.set(term);
  }

  setCategory(categoryId: string | null) {
    this._selectedCategory.set(categoryId);
  }

  setDifficulty(diff: string | null) {
    this._selectedDifficulty.set(diff);
  }

  setMaxPrepTime(minutes: number | null) {
    this._maxPrepTime.set(minutes);
  }

  setSortBy(sort: 'none' | 'titleAsc' | 'titleDesc' | 'prepTimeAsc' | 'caloriesAsc' | 'newest') {
    this._sortBy.set(sort);
  }

  clearFilters() {
    this._searchTerm.set('');
    this._selectedCategory.set(null);
    this._selectedDifficulty.set(null);
    this._maxPrepTime.set(null);
    this._sortBy.set('none');
  }

  constructor(private toast: ToastService, private auth: AuthService) {
    this.loadRecipes();
  }
}

export default RecipeService;

import { Component, Output, EventEmitter, Input } from '@angular/core';
import { NgIf, NgFor } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Recipe } from '../../models/recipe';
import { AuthService } from '../../services/auth.service';
import { ALL_CATEGORIES, CATEGORY_ID_MAP, RecipeCategory } from '../../models/categories';

@Component({
  selector: 'app-recipe-editor',
  standalone: true,
  imports: [NgIf, NgFor, ReactiveFormsModule],
  templateUrl: './recipe-editor.html',
  styleUrl: './recipe-editor.scss',
})
export class RecipeEditor {
  @Output() close = new EventEmitter<void>();
  @Output() save = new EventEmitter<Recipe>();
  @Input() initialRecipe?: Recipe | null;

  form: FormGroup;
  categories = ALL_CATEGORIES;


  constructor(private fb: FormBuilder, private auth: AuthService) {
    this.form = this.fb.group({
      title: ['', Validators.required],
      description: ['', Validators.required],
      imageUrl: [''],
      category: [''],
      difficulty: ['könnyű'],
      prepTime: [30],
      calories: [0],
      servings: [1],
      ingredientsText: [''], // newline separated ingredient lines: "name|amount|unit"
      stepsText: [''], // newline separated steps
      protein: [0],
      carbs: [0],
      fat: [0],
      isPublic: [true]
    });
    // If initialRecipe is provided after creation, it will be set via the Input setter below (Angular will call property assignment before change detection)
  }

  ngOnChanges() {
    this.applyInitial();
  }

  private applyInitial() {
    const r = this.initialRecipe as any;
    if (!r) {
      this.form.reset({
        title: '', description: '', imageUrl: '', category: '', difficulty: 'könnyű', prepTime: 30,
        calories: 0, servings: 1, ingredientsText: '', stepsText: '', protein: 0, carbs: 0, fat: 0, isPublic: true
      });
      return;
    }

    // Map categoryId back to category label if possible
    let categoryLabel = '';
    for (const [label, id] of Object.entries(CATEGORY_ID_MAP)) {
      if (id === r.categoryId) { categoryLabel = label; break; }
    }

    const ingredientsText = (r.ingredients || []).map((ing: any) => `${ing.ingredientName || ''}|${ing.amount || 0}|${ing.unit || ''}`).join('\n');
    const stepsText = (r.steps || []).join('\n');

    this.form.patchValue({
      title: r.title || '',
      description: r.description || '',
      imageUrl: r.imageUrl || r.image || '',
      category: categoryLabel,
      difficulty: r.difficulty || 'könnyű',
      prepTime: r.prepTime || 0,
      calories: r.calories || 0,
      servings: r.servings || 1,
      ingredientsText,
      stepsText,
      protein: r.nutrition?.protein || 0,
      carbs: r.nutrition?.carbs || 0,
      fat: r.nutrition?.fat || 0,
      isPublic: !!r.isPublic
    });
  }



  saveRecipe() {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const v = this.form.value;

    const ingredients = (v.ingredientsText || '').split('\n').map((line: string) => line.trim()).filter((l: string) => !!l).map((l: string, idx: number) => {
      const parts = l.split('|').map((p: string) => p.trim());
      return {
        ingredientId: `ing_${Date.now()}_${idx}`,
        ingredientName: parts[0] || 'ingredient',
        amount: Number(parts[1] || 0),
        unit: parts[2] || ''
      };
    });

    const steps = (v.stepsText || '').split('\n').map((s: string) => s.trim()).filter((s: string) => !!s);

    const now = new Date().toISOString();
    const categoryId = v.category ? (CATEGORY_ID_MAP[v.category] || null) : null;

    const id = (this.initialRecipe && this.initialRecipe.id) ? this.initialRecipe.id : `recipe_${Date.now()}`;

    const recipe: Recipe = {
      id,
      title: v.title,
      description: v.description,
      imageUrl: v.imageUrl || undefined,
      categoryId: categoryId || undefined,
      difficulty: v.difficulty || 'könnyű',
      prepTime: Number(v.prepTime) || 0,
      calories: Number(v.calories) || 0,
      servings: Number(v.servings) || 1,
      diet: [],
      nutrition: {
        protein: Number(v.protein) || 0,
        carbs: Number(v.carbs) || 0,
        fat: Number(v.fat) || 0
      },
      ingredients: ingredients,
      steps: steps,
      ownerId: this.auth?.uid?.() || undefined,
      isPublic: !!v.isPublic,
      createdAt: (this.initialRecipe && this.initialRecipe.createdAt) ? this.initialRecipe.createdAt : now,
      updatedAt: now
    };

    this.save.emit(recipe);
  }
}

